# метка «без мяса и рыбы»: все мясные и рыбные продукты из этой партии; «кури» вместо «кур», чтобы не ловить кукурузу и курагу
MEAT = re.compile(r'(говядин|говяж|свин|баранин|бараний|телятин|теляч|кури|цыпл|индейк|утк|утин|фарш|бекон|ветчин|колбас|сосиск|сардельк|пельмен|ростбиф|пастром|пепперони|салями|печень\b|кролик|минтай|горбуш|тунец|рыб|сельд|креветк|треск|хек|сёмг|форел|скумбри|кальмар|краб|кет[аы]\b|пикш|тилапи|шпрот|сардин|анчоус|икра|мидии)', re.I)
out, errs = [], []
for x in D:
    tot = dict(kcal=0.0, p=0.0, f=0.0, c=0.0); raw = 0; ings = []
    for name, g in x['i']:
        raw += g
        if name == W: ings.append({'n': 'Вода', 'g': g}); continue
        c = CORE.get(name)
        if not c: errs.append((x['n'], name)); continue
        for k in tot: tot[k] += c[k] * g / 100
        ings.append({'n': name, 'g': g})
    k = round(tot['kcal']); P, F, C = round(tot['p'], 1), round(tot['f'], 1), round(tot['c'], 1)
    tags = list(x.get('tag', []))
    if P >= 25: tags.append('белковое')
    if x['t'] <= 15: tags.append('быстро')
    if len([1 for n, g in x['i'] if n != W]) <= 4: tags.append('мало ингредиентов')
    if not any(MEAT.search(n) and not n.startswith('Яйцо') for n, g in x['i']): tags.append('без мяса и рыбы')
    rec = dict(n=x['n'], meal=x['m'], d=x['d'], time=x['t'], out=x['out'], kcal=k, p=P, f=F, c=C,
               k100=round(k / x['out'] * 100), ing=ings, steps=x['s'], tip=x['tip'], tags=tags)
    if 'batch' in x: rec['batch'] = x['batch']
    if 'plus' in x:
        pn, pg = x['plus']; pc = CORE.get(pn)
        if not pc: errs.append((x['n'], 'plus: ' + pn)); continue
        rec['plus'] = f"+{pg} г «{pn}»: +{round(pc['p']*pg/100)} г белка, +{round(pc['kcal']*pg/100)} ккал"
    out.append(rec)
if errs:
    print('НЕТ В БАЗЕ:', errs); sys.exit(1)
json.dump(out, open(sys.argv[2], 'w', encoding='utf-8'), ensure_ascii=False, indent=0)
for r in out:
    print(f"{r['meal']:8} {r['kcal']:4} ккал Б{r['p']:5} Ж{r['f']:5} У{r['c']:5} | {r['k100']:3}/100г | {r['n']} | {', '.join(r['tags'])}")
